	/// <summary>Registers every key x language with PackmasterApi.AddLoc.</summary>
	public static void RegisterAll()
	{
		foreach (var (language, values) in Values)
		{
			var ui = new Dictionary<string, string>();
			var library = new Dictionary<string, string>();
			for (var i = 0; i < Keys.Length; i++)
			{
				(Keys[i] == "pool.tip" ? library : ui)["PACKMASTER_LIB." + Keys[i]] = values[i];
			}
			PackmasterApi.AddLoc("gameplay_ui", language, ui);
			PackmasterApi.AddLoc("card_library", language, library);
		}
	}
}
